begin;
with j as (select * from jsonb_to_recordset($law7d0017$[{"code_id":"BK_RF","article_number":"78.4","version_date":"1998-07-31","article_text":"1. В бюджетах бюджетной системы Российской Федерации могут предусматриваться субсидии юридическим лицам,  индивидуальным предпринимателям,  а также физическим лицам - производителям товаров,  работ,  услуг в целях финансового обеспечения исполнения государственного (муниципального)  социального заказа на оказание государственных (муниципальных)  услуг в социальной сфере в соответствии с Федеральным законом от 13 июля 2020 года № 189-ФЗ \"О государственном (муниципальном)  социальном заказе на оказание государственных (муниципальных)  услуг в социальной сфере\" и принятыми в соответстви\n\n11. Государственным корпорациям могут предоставляться субсидии,  предусмотренные подпунктом 1 пункта 1 настоящей статьи,  в целях исполнения принятых в случаях,  определенных федеральными законами,  предусматривающими создание государственных корпораций,  нормативных правовых актов  Правительства  Российской Федерации об увеличении уставного капитала государственной корпорации,  подлежащего формированию за счет последующего предоставления имущественных взносов Российской Федерации. (Дополнение пунктом - Федеральный закон от 28.11.2018 № 453-ФЗ)2. Предоставление предусмотренных настоящей статьей субсидий на цели,  указанные в подпунктах 21 и 3 пункта 1 настоящей статьи,  включая субсидии в виде имущественного взноса Российской Федерации,  осуществляется в соответствии с решениями,  которые принимаются в форме правовых актов  Правительства  Российской Федерации в определяемом им порядке. В случае,  если подготовка обоснования инвестиций для объекта капитального строительства в соответствии с законодательством Российской Федерации является обязательной,  указанные решения в отношении таких объектов капитального строительства принимаются в том числе на основании подготовленного в установленном законодательством Российской Федерации порядке обоснования инвестиций и результатов его технологического и ценового аудита,  а также утвержденного задания на проектирование. (В редакции  федеральных законов от 19.07.2018 № 222-ФЗ,  от 29.11.2021 № 384-ФЗ,  от 04.08.2023 № 416-ФЗ)3. Предоставление предусмотренных настоящей статьей субсидий (за исключением субсидий на цели,  указанные в пункте 11 настоящей статьи,  а также субсидий,  предоставляемых государственным корпорациям,  публично-правовым компаниям при осуществлении ими в соответствии с настоящим Кодексом полномочий главного распорядителя бюджетных средств и получателя бюджетных средств)  осуществляется в соответствии с соглашением о предоставлении субсидии,  заключаемым между получателем средств федерального бюджета,  предоставляющим субсидию,  и государственной корпорацией (компанией)  или публично-правовой компанией (далее в настоящей статье - соглашение о предоставлении субсидии) . (В редакции федеральных законов от 28.11.2018 № 453-ФЗ,  от 22.12.2020 № 448-ФЗ)Соглашение о предоставлении субсидии и дополнительные соглашения к указанному соглашению,  предусматривающие внесение в него изменений или его расторжение,  заключаются в соответствии с типовыми формами,  утверждаемыми Министерством финансов Российской Федерации. (Дополнение абзацем - Федеральный закон от 27.12.2018 № 504-ФЗ)4. Правила предоставления предусмотренных настоящей статьей субсидий (за исключением субсидий на цели,  указанные в пункте 11 настоящей статьи)  устанавливаются нормативными правовыми актами  Правительства  Российской Федерации,  определяющими в том числе: (В редакции Федерального закона от 28.11.2018 № 453-ФЗ)1)  цели,  условия и порядок предоставления субсидий,  а также перечень затрат,  источником финансового обеспечения (возмещения)  которых являются субсидии,  и результаты предоставления субсидий (иные показатели) ; (В редакции Федерального закона от 01.04.2020 № 71-ФЗ)2)  требования к соглашениям о предоставлении субсидий,  в том числе указанные в пункте 9 настоящей статьи,  а также сроки (требования к срокам)  заключения соглашений о предоставлении субсидий и перечисления субсидий государственным корпорациям (компаниям) ,  публично-правовым компаниям;3)  требования к порядку и срокам представления отчетности об осуществлении расходов,  источником финансового обеспечения которых являются субсидии,  предоставляемые в целях финансового обеспечения затрат государственных корпораций (компаний) ,  публично-правовых компаний,  а также о достижении государственными корпорациями (компаниями) ,  публично-правовыми компаниями,  юридическими лицами,  акции (доли)  которых принадлежат указанным государственным корпорациям (компаниям) ,  публично-правовым компаниям,  и (или)  дочерними обществами таких юридических лиц результатов предоставления субсидий (иных показателей) ; (В редакции Федерального закона от 01.04.2020 № 71-ФЗ)4)  порядок возврата государственными корпорациями (компаниями) ,  публично-правовыми компаниями соответствующих средств в федеральный бюджет в случае нарушения целей,  условий и порядка предоставления субсидий; (В редакции Федерального закона от 27.12.2018 № 504-ФЗ)5)  случаи и порядок возврата в федеральный бюджет остатков субсидий,  предоставленных в целях финансового обеспечения затрат государственных корпораций (компаний) ,  публично-правовых компаний,  не использованных в отчетном финансовом году,  за исключением субсидий,  предоставленных в пределах суммы,  необходимой для оплаты денежных обязательств государственных корпораций (компаний) ,  публично-правовых компаний,  источником финансового обеспечения которых являются субсидии;6)  положения о проверке получателями средств федерального бюджета,  предоставившими субсидии,  и органами государственного финансового контроля соблюдения целей,  условий и порядка предоставления субсидий. (В редакции Федерального закона от 01.07.2021 № 244-ФЗ)41. Предоставление субсидий на цели,  указанные в пункте 11 настоящей статьи,  осуществляется в порядке,  определяемом федеральными законами,  предусматривающими создание государственных корпораций. (Дополнение пунктом - Федеральный закон от 28.11.2018 № 453-ФЗ)42. В дополнение к положениям,  установленным пунктом 4 настоящей статьи,  в определенные указанным пунктом правила предоставления субсидий,  предоставление которых не осуществляется единовременно при условии достижения результатов предоставления субсидии,  могут включаться информация о последовательном достижении результатов предоставления субсидии (иных показателей)  и порядок предоставления этой информации. (Дополнение пунктом - Федеральный закон от 26.12.2024 № 488-ФЗ)5. Предусмотренные настоящей статьей субсидии утверждаются федеральным законом о федеральном бюджете в качестве отдельного приложения к нему с указанием государственной корпорации (компании) ,  публично-правовой компании,  объема и цели предоставляемой субсидии,  за исключением субсидий,  источником финансового обеспечения которых являются бюджетные ассигнования резервных фондов Президента Российской Федерации и  Правительства  Российской Федерации,  а также субсидий на цели,  указанные в пункте 11 настоящей статьи,  при внесении изменений в сводную бюджетную роспись в соответствии с абзацем двадцать первым пункта 7 статьи 217 настоящего Кодекса. (В редакции Федерального закона от 28.11.2018 № 453-ФЗ)6. Использование государственной корпорацией (компанией) ,  публично-правовой компанией предусмотренной настоящей статьей субсидии на цели предоставления взносов в уставные (складочные)  капиталы юридических лиц,  акции (доли)  которых принадлежат указанным государственной корпорации (компании) ,  публично-правовой компании,  в том числе для последующего предоставления взносов в уставные (складочные)  капиталы дочерних обществ таких юридических лиц,  допускается при условии,  если использование субсидии на эти цели предусмотрено нормативными правовыми актами,  указанными в пунктах 2 и 4 настоящей статьи,  в порядке,  сроки и на условиях,  которые определяются этими актами.7. (Пункт утратил силу - Федеральный закон от 27.12.2019 № 479-ФЗ)8. Обязательными условиями предоставления предусмотренных настоящей статьей субсидий государственным корпорациям (компаниям) ,  публично-правовым компаниям являются:1)  соблюдение государственными корпорациями (компаниями) ,  публично-правовыми компаниями,  юридическими лицами,  акции (доли)  которых принадлежат указанным государственным корпорациям (компаниям) ,  публично-правовым компаниям,  и (или)  дочерними обществами таких юридических лиц при осуществлении закупок за счет средств,  полученных на цели,  указанные в подпункте 3 пункта 1 настоящей статьи,  а также закупок в целях строительства (реконструкции)  объектов капитального строительства,  указанных в подпункте 31 пункта 1 настоящей статьи,  подлежащих в установленных федеральными законами случаях передаче в государственную (муниципальную)  собственность,  и закупок в целях,  указанных в подпункте 21 пункта 1 настоящей статьи,  положений,  установленных законодательством Российской Федерации о контрактной системе в сфере закупок товаров,  работ,  услуг для обеспечения государственных и муниципальных нужд; (В редакции  федеральных законов от 01.04.2020 № 71-ФЗ,  от 21.11.2022 № 448-ФЗ)2)  запрет на приобретение за счет полученных средств,  предоставленных в целях финансового обеспечения затрат государственных корпораций (компаний) ,  публично-правовых компаний,  иностранной валюты,  за исключением операций,  осуществляемых в соответствии с валютным законодательством Российской Федерации при закупке (поставке)  высокотехнологичного импортного оборудования,  сырья и комплектующих изделий,  а также связанных с достижением целей предоставления этих средств иных операций,  определенных нормативными правовыми актами,  указанными в пунктах 2 и 4 настоящей статьи;3)  отсутствие у государственных корпораций (компаний) ,  публично-правовых компаний,  а в случае предоставления субсидий в целях предоставления средств,  указанных в пункте 6 настоящей статьи,  юридическим лицам,  акции (доли)  которых принадлежат указанным государственным корпорациям (компаниям) ,  публично-правовым компаниям,  и (или)  дочерним обществам таких юридических лиц,  также соответственно у указанных юридических лиц и (или)  дочерних обществ на первое число месяца,  предшествующего месяцу,  в котором заключаются соглашения о предоставлении субсидий,  задолженности по налогам,  сборам и иным обязательным платежам в бюджеты бюджетной системы Российской Федерации,  срок исполнения по которым наступил в соответствии с законодательством Российской Федерации;4)  наличие мероприятий,  для реализации которых государственным корпорациям (компаниям) ,  публично-правовым компаниям предоставляются субсидии,  в программах (стратегиях)  деятельности государственных корпораций (компаний) ,  публично-правовых компаний или в определяющих цели и задачи их деятельности иных документах,  предусмотренных нормативными правовыми актами,  указанными в пунктах 2 и 4 настоящей статьи. (Дополнение подпунктом - Федеральный закон от 27.12.2018 № 504-ФЗ)9. Соглашение о предоставлении субсидии должно содержать в том числе:1)  цель предоставления субсидии и ее объем с распределением по годам,  а в случае предоставления субсидии на цели,  указанные в подпункте 3 пункта 1 настоящей статьи,  в отношении каждого объекта капитального строительства и (или)  объекта недвижимого имущества - его наименование,  мощность,  сроки строительства (реконструкции,  в том числе с элементами реставрации,  технического перевооружения)  и (или)  приобретения,  стоимость,  а также общий объем капитальных вложений за счет всех источников финансового обеспечения,  в том числе объем предоставляемой субсидии;2)  перечень затрат,  источником финансового обеспечения (возмещения)  которых является субсидия,  а также результаты предоставления субсидии (иные показатели)  и условие об их достижении государственной корпорацией (компанией) ,  публично-правовой компанией,  юридическими лицами,  акции (доли)  которых принадлежат указанным государственной корпорации (компании) ,  публично-правовой компании,  и (или)  дочерними обществами таких юридических лиц; (В редакции Федерального закона от 01.04.2020 № 71-ФЗ)3)  положения,  устанавливающие права и обязанности сторон соглашения о предоставлении субсидии и порядок их взаимодействия при реализации соглашения о предоставлении субсидии;4)  условия,  предусмотренные пунктом 8 настоящей статьи;5)  обязанность государственной корпорации (компании) ,  публично-правовой компании по возврату в федеральный бюджет остатка субсидии,  предоставленной в целях финансового обеспечения затрат государственной корпорации (компании) ,  публично-правовой компании,  не использованного в отчетном финансовом году (за исключением субсидии,  предоставленной в пределах суммы,  необходимой для оплаты денежных обязательств государственной корпорации (компании) ,  публично-правовой компании,  источником финансового обеспечения которых является указанная субсидия) ,  если получателем средств федерального бюджета,  предоставляющим субсидию,  не принято в установленном Правительством Российской Федерации порядке решение:о наличии потребности в использовании этих средств на цели предоставления субсидии в текущем финансовом году;об использовании этих средств на иные цели,  определенные федеральным законом о федеральном бюджете на текущий финансовый год и плановый период,  при условии сокращения субсидий,  предусмотренных данным федеральным законом и подлежащих предоставлению в текущем финансовом году соответствующим государственной корпорации (компании) ,  публично-правовой компании на указанные цели;6)  порядок и сроки представления отчетности об осуществлении расходов,  источником финансового обеспечения которых является субсидия,  предоставленная в целях финансового обеспечения затрат государственной корпорации (компании) ,  публично-правовой компании,  а также о достижении государственной корпорацией (компанией) ,  публично-правовой компанией,  юридическими лицами,  акции (доли)  которых принадлежат указанным государственной корпорации (компании) ,  публично-правовой компании,  и (или)  дочерними обществами таких юридических лиц результатов предоставления субсидии (иных показателей) ; (В редакции Федерального закона от 01.04.2020 № 71-ФЗ)7)  положения,  устанавливающие право получателя средств федерального бюджета,  предоставляющего субсидию,  на проведение проверок соблюдения государственной корпорацией (компанией) ,  публично-правовой компанией условий,  установленных соглашением о предоставлении субсидии;8)  ответственность государственной корпорации (компании) ,  публично-правовой компании за нарушение условий,  определенных соглашением о предоставлении субсидии.10. При предоставлении предусмотренной настоящей статьей субсидии государственной корпорации,  публично-правовой компании,  осуществляющим в соответствии с настоящим Кодексом полномочия главного распорядителя бюджетных средств и получателя бюджетных средств,  положения,  подлежащие в соответствии с пунктом 9 настоящей статьи включению в соглашение о предоставлении субсидии,  устанавливаются нормативными правовыми актами,  указанными в пунктах 2 и (или)  4 настоящей статьи. (В редакции Федерального закона от 22.12.2020 № 448-ФЗ)11. Соглашения о предоставлении субсидий могут заключаться на срок,  превышающий срок действия доведенных лимитов бюджетных обязательств,  в пределах средств,  предусмотренных на соответствующие цели решениями,  указанными в пункте 2 настоящей статьи,  или в случаях,  предусмотренных иными решениями  Правительства  Российской Федерации,  которые принимаются в определяемом Правительством Российской Федерации порядке. (В редакции федеральных законов от 15.10.2020 № 327-ФЗ,  от 30.04.2021 № 108-ФЗ)Заключение договора (соглашения)  о предоставлении субсидии государственной корпорации (компании) ,  публично-правовой компании,  являющейся стороной соглашения о защите и поощрении капиталовложений,  заключенного в порядке,  установленном Федеральным законом от 1 апреля 2020 года № 69-ФЗ \"О защите и поощрении капиталовложений в Российской Федерации\",  на срок,  превышающий срок действия утвержденных лимитов бюджетных обязательств,  осуществляется в пределах сроков и объемов возмещения затрат,  определяемых в соответствии с указанным Федеральным законом. (Дополнение абзацем - Федеральный закон от 30.04.2021 № 108-ФЗ)12. В случаях,  определенных федеральными законами (за исключением федерального закона о федеральном бюджете) ,  иными нормативными правовыми актами о создании публично-правовых компаний,  государственным корпорациям (компаниям) ,  публично-правовым компаниям предоставляются субсидии на цели,  указанные в подпункте 3 пункта 1 настоящей статьи,  на осуществление ими капитальных вложений в целях строительства объектов капитального строительства,  подлежащих передаче в государственную собственность Российской Федерации.Переданные в государственную собственность Российской Федерации объекты капитального строительства,  указанные в абзаце первом настоящего пункта,  закрепляются в установленном порядке на праве оперативного управления за федеральными государственными учреждениями либо на праве оперативного управления или хозяйственного ведения за федеральными государственными унитарными предприятиями с последующим увеличением стоимости основных средств,  находящихся на праве оперативного управления у федеральных государственных учреждений либо на праве оперативного управления или хозяйственного ведения у федеральных государственных унитарных предприятий,  а также увеличением уставного фонда указанных предприятий,  основанных на праве хозяйственного ведения,  в соответствии с решениями,  указанными в пункте 2 настоящей статьи.121. В случае предоставления субсидий на цели,  предусмотренные подпунктом 21 пункта 1 настоящей статьи,  исключительные права на созданные или приобретенные за счет средств федерального бюджета программы для электронных вычислительных машин и иные результаты интеллектуальной деятельности,  связанные с созданием и развитием соответствующих государственных информационных систем,  на технические средства,  предназначенные для обработки информации,  содержащейся в государственных информационных системах,  в том числе программно-технические средства и средства защиты информации,  приобретенные за счет средств федерального бюджета,  а также права использования указанных программ,  иных результатов интеллектуальной деятельности,  технических средств принадлежат Российской Федерации.Государственная регистрация прав,  указанных в абзаце первом настоящего пункта,  обеспечивается в установленном порядке федеральными органами государственной власти,  предоставляющими субсидии.Переданные в государственную собственность Российской Федерации технические средства,  указанные в абзаце первом настоящего пункта,  закрепляются в установленном порядке за федеральными органами государственной власти,  предоставляющими субсидии.В соглашение о предоставлении субсидии в дополнение к предусмотренным пунктом 9 настоящей статьи положениям включаются положения об условиях предоставления государственным корпорациям (компаниям) ,  публично-правовым компаниям прав использования программ для электронных вычислительных машин и иных результатов интеллектуальной деятельности,  связанных с созданием и развитием соответствующих государственных информационных систем,  и об условиях пользования техническими средствами,  предназначенными для обработки информации,  содержащейся в государственных информационных системах,  необходимых для реализации определенных федеральными законами функций оператора таких систем.(Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)13. В случае нарушения государственной корпорацией (компанией) ,  публично-правовой компанией целей,  условий и порядка предоставления предусмотренной настоящей статьей субсидии соответствующие средства подлежат возврату государственной корпорацией (компанией) ,  публично-правовой компанией в федеральный бюджет в порядке,  определенном нормативным правовым актом,  указанным в пункте 4 настоящей статьи.(Дополнение статьей - Федеральный закон от 18.07.2017 № 178-ФЗ)Статья 784. Предоставление субсидий в целях финансового обеспечения исполнения государственного (муниципального)  социального заказа на оказание государственных (муниципальных)  услуг в социальной сфере1. В бюджетах бюджетной системы Российской Федерации могут предусматриваться субсидии юридическим лицам,  индивидуальным предпринимателям,  а также физическим лицам - производителям товаров,  работ,  услуг в целях финансового обеспечения исполнения государственного (муниципального)  социального заказа на оказание государственных (муниципальных)  услуг в социальной сфере в соответствии с Федеральным законом от 13 июля 2020 года № 189-ФЗ \"О государственном (муниципальном)  социальном заказе на оказание государственных (муниципальных)  услуг в социальной сфере\" и принятыми в соответстви\n\n11. Государственным корпорациям могут предоставляться субсидии,  предусмотренные подпунктом 1 пункта 1 настоящей статьи,  в целях исполнения принятых в случаях,  определенных федеральными законами,  предусматривающими создание государственных корпораций,  нормативных правовых актов  Правительства  Российской Федерации об увеличении уставного капитала государственной корпорации,  подлежащего формированию за счет последующего предоставления имущественных взносов Российской Федерации. (Дополнение пунктом - Федеральный закон от 28.11.2018 № 453-ФЗ)\n\n2. Предоставление предусмотренных настоящей статьей субсидий на цели,  указанные в подпунктах 21 и 3 пункта 1 настоящей статьи,  включая субсидии в виде имущественного взноса Российской Федерации,  осуществляется в соответствии с решениями,  которые принимаются в форме правовых актов  Правительства  Российской Федерации в определяемом им порядке. В случае,  если подготовка обоснования инвестиций для объекта капитального строительства в соответствии с законодательством Российской Федерации является обязательной,  указанные решения в отношении таких объектов капитального строительства принимаются в том числе на основании подготовленного в установленном законодательством Российской Федерации порядке обоснования инвестиций и результатов его технологического и ценового аудита,  а также утвержденного задания на проектирование. (В редакции  федеральных законов от 19.07.2018 № 222-ФЗ,  от 29.11.2021 № 384-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\n3. Предоставление предусмотренных настоящей статьей субсидий (за исключением субсидий на цели,  указанные в пункте 11 настоящей статьи,  а также субсидий,  предоставляемых государственным корпорациям,  публично-правовым компаниям при осуществлении ими в соответствии с настоящим Кодексом полномочий главного распорядителя бюджетных средств и получателя бюджетных средств)  осуществляется в соответствии с соглашением о предоставлении субсидии,  заключаемым между получателем средств федерального бюджета,  предоставляющим субсидию,  и государственной корпорацией (компанией)  или публично-правовой компанией (далее в настоящей статье - соглашение о предоставлении субсидии) . (В редакции федеральных законов от 28.11.2018 № 453-ФЗ,  от 22.12.2020 № 448-ФЗ)\n\nСоглашение о предоставлении субсидии и дополнительные соглашения к указанному соглашению,  предусматривающие внесение в него изменений или его расторжение,  заключаются в соответствии с типовыми формами,  утверждаемыми Министерством финансов Российской Федерации. (Дополнение абзацем - Федеральный закон от 27.12.2018 № 504-ФЗ)\n\n4. Правила предоставления предусмотренных настоящей статьей субсидий (за исключением субсидий на цели,  указанные в пункте 11 настоящей статьи)  устанавливаются нормативными правовыми актами  Правительства  Российской Федерации,  определяющими в том числе: (В редакции Федерального закона от 28.11.2018 № 453-ФЗ)\n\n1)  цели,  условия и порядок предоставления субсидий,  а также перечень затрат,  источником финансового обеспечения (возмещения)  которых являются субсидии,  и результаты предоставления субсидий (иные показатели) ; (В редакции Федерального закона от 01.04.2020 № 71-ФЗ)\n\n2)  требования к соглашениям о предоставлении субсидий,  в том числе указанные в пункте 9 настоящей статьи,  а также сроки (требования к срокам)  заключения соглашений о предоставлении субсидий и перечисления субсидий государственным корпорациям (компаниям) ,  публично-правовым компаниям;\n\n3)  требования к порядку и срокам представления отчетности об осуществлении расходов,  источником финансового обеспечения которых являются субсидии,  предоставляемые в целях финансового обеспечения затрат государственных корпораций (компаний) ,  публично-правовых компаний,  а также о достижении государственными корпорациями (компаниями) ,  публично-правовыми компаниями,  юридическими лицами,  акции (доли)  которых принадлежат указанным государственным корпорациям (компаниям) ,  публично-правовым компаниям,  и (или)  дочерними обществами таких юридических лиц результатов предоставления субсидий (иных показателей) ; (В редакции Федерального закона от 01.04.2020 № 71-ФЗ)\n\n4)  порядок возврата государственными корпорациями (компаниями) ,  публично-правовыми компаниями соответствующих средств в федеральный бюджет в случае нарушения целей,  условий и порядка предоставления субсидий; (В редакции Федерального закона от 27.12.2018 № 504-ФЗ)\n\n5)  случаи и порядок возврата в федеральный бюджет остатков субсидий,  предоставленных в целях финансового обеспечения затрат государственных корпораций (компаний) ,  публично-правовых компаний,  не использованных в отчетном финансовом году,  за исключением субсидий,  предоставленных в пределах суммы,  необходимой для оплаты денежных обязательств государственных корпораций (компаний) ,  публично-правовых компаний,  источником финансового обеспечения которых являются субсидии;\n\n6)  положения о проверке получателями средств федерального бюджета,  предоставившими субсидии,  и органами государственного финансового контроля соблюдения целей,  условий и порядка предоставления субсидий. (В редакции Федерального закона от 01.07.2021 № 244-ФЗ)\n\n41. Предоставление субсидий на цели,  указанные в пункте 11 настоящей статьи,  осуществляется в порядке,  определяемом федеральными законами,  предусматривающими создание государственных корпораций. (Дополнение пунктом - Федеральный закон от 28.11.2018 № 453-ФЗ)\n\n42. В дополнение к положениям,  установленным пунктом 4 настоящей статьи,  в определенные указанным пунктом правила предоставления субсидий,  предоставление которых не осуществляется единовременно при условии достижения результатов предоставления субсидии,  могут включаться информация о последовательном достижении результатов предоставления субсидии (иных показателей)  и порядок предоставления этой информации. (Дополнение пунктом - Федеральный закон от 26.12.2024 № 488-ФЗ)\n\n5. Предусмотренные настоящей статьей субсидии утверждаются федеральным законом о федеральном бюджете в качестве отдельного приложения к нему с указанием государственной корпорации (компании) ,  публично-правовой компании,  объема и цели предоставляемой субсидии,  за исключением субсидий,  источником финансового обеспечения которых являются бюджетные ассигнования резервных фондов Президента Российской Федерации и  Правительства  Российской Федерации,  а также субсидий на цели,  указанные в пункте 11 настоящей статьи,  при внесении изменений в сводную бюджетную роспись в соответствии с абзацем двадцать первым пункта 7 статьи 217 настоящего Кодекса. (В редакции Федерального закона от 28.11.2018 № 453-ФЗ)\n\n6. Использование государственной корпорацией (компанией) ,  публично-правовой компанией предусмотренной настоящей статьей субсидии на цели предоставления взносов в уставные (складочные)  капиталы юридических лиц,  акции (доли)  которых принадлежат указанным государственной корпорации (компании) ,  публично-правовой компании,  в том числе для последующего предоставления взносов в уставные (складочные)  капиталы дочерних обществ таких юридических лиц,  допускается при условии,  если использование субсидии на эти цели предусмотрено нормативными правовыми актами,  указанными в пунктах 2 и 4 настоящей статьи,  в порядке,  сроки и на условиях,  которые определяются этими актами.\n\n7. (Пункт утратил силу - Федеральный закон от 27.12.2019 № 479-ФЗ)\n\n8. Обязательными условиями предоставления предусмотренных настоящей статьей субсидий государственным корпорациям (компаниям) ,  публично-правовым компаниям являются:\n\n1)  соблюдение государственными корпорациями (компаниями) ,  публично-правовыми компаниями,  юридическими лицами,  акции (доли)  которых принадлежат указанным государственным корпорациям (компаниям) ,  публично-правовым компаниям,  и (или)  дочерними обществами таких юридических лиц при осуществлении закупок за счет средств,  полученных на цели,  указанные в подпункте 3 пункта 1 настоящей статьи,  а также закупок в целях строительства (реконструкции)  объектов капитального строительства,  указанных в подпункте 31 пункта 1 настоящей статьи,  подлежащих в установленных федеральными законами случаях передаче в государственную (муниципальную)  собственность,  и закупок в целях,  указанных в подпункте 21 пункта 1 настоящей статьи,  положений,  установленных законодательством Российской Федерации о контрактной системе в сфере закупок товаров,  работ,  услуг для обеспечения государственных и муниципальных нужд; (В редакции  федеральных законов от 01.04.2020 № 71-ФЗ,  от 21.11.2022 № 448-ФЗ)\n\n2)  запрет на приобретение за счет полученных средств,  предоставленных в целях финансового обеспечения затрат государственных корпораций (компаний) ,  публично-правовых компаний,  иностранной валюты,  за исключением операций,  осуществляемых в соответствии с валютным законодательством Российской Федерации при закупке (поставке)  высокотехнологичного импортного оборудования,  сырья и комплектующих изделий,  а также связанных с достижением целей предоставления этих средств иных операций,  определенных нормативными правовыми актами,  указанными в пунктах 2 и 4 настоящей статьи;\n\n3)  отсутствие у государственных корпораций (компаний) ,  публично-правовых компаний,  а в случае предоставления субсидий в целях предоставления средств,  указанных в пункте 6 настоящей статьи,  юридическим лицам,  акции (доли)  которых принадлежат указанным государственным корпорациям (компаниям) ,  публично-правовым компаниям,  и (или)  дочерним обществам таких юридических лиц,  также соответственно у указанных юридических лиц и (или)  дочерних обществ на первое число месяца,  предшествующего месяцу,  в котором заключаются соглашения о предоставлении субсидий,  задолженности по налогам,  сборам и иным обязательным платежам в бюджеты бюджетной системы Российской Федерации,  срок исполнения по которым наступил в соответствии с законодательством Российской Федерации;\n\n4)  наличие мероприятий,  для реализации которых государственным корпорациям (компаниям) ,  публично-правовым компаниям предоставляются субсидии,  в программах (стратегиях)  деятельности государственных корпораций (компаний) ,  публично-правовых компаний или в определяющих цели и задачи их деятельности иных документах,  предусмотренных нормативными правовыми актами,  указанными в пунктах 2 и 4 настоящей статьи. (Дополнение подпунктом - Федеральный закон от 27.12.2018 № 504-ФЗ)\n\n9. Соглашение о предоставлении субсидии должно содержать в том числе:\n\n1)  цель предоставления субсидии и ее объем с распределением по годам,  а в случае предоставления субсидии на цели,  указанные в подпункте 3 пункта 1 настоящей статьи,  в отношении каждого объекта капитального строительства и (или)  объекта недвижимого имущества - его наименование,  мощность,  сроки строительства (реконструкции,  в том числе с элементами реставрации,  технического перевооружения)  и (или)  приобретения,  стоимость,  а также общий объем капитальных вложений за счет всех источников финансового обеспечения,  в том числе объем предоставляемой субсидии;\n\n2)  перечень затрат,  источником финансового обеспечения (возмещения)  которых является субсидия,  а также результаты предоставления субсидии (иные показатели)  и условие об их достижении государственной корпорацией (компанией) ,  публично-правовой компанией,  юридическими лицами,  акции (доли)  которых принадлежат указанным государственной корпорации (компании) ,  публично-правовой компании,  и (или)  дочерними обществами таких юридических лиц; (В редакции Федерального закона от 01.04.2020 № 71-ФЗ)\n\n3)  положения,  устанавливающие права и обязанности сторон соглашения о предоставлении субсидии и порядок их взаимодействия при реализации соглашения о предоставлении субсидии;\n\n4)  условия,  предусмотренные пунктом 8 настоящей статьи;\n\n5)  обязанность государственной корпорации (компании) ,  публично-правовой компании по возврату в федеральный бюджет остатка субсидии,  предоставленной в целях финансового обеспечения затрат государственной корпорации (компании) ,  публично-правовой компании,  не использованного в отчетном финансовом году (за исключением субсидии,  предоставленной в пределах суммы,  необходимой для оплаты денежных обязательств государственной корпорации (компании) ,  публично-правовой компании,  источником финансового обеспечения которых является указанная субсидия) ,  если получателем средств федерального бюджета,  предоставляющим субсидию,  не принято в установленном Правительством Российской Федерации порядке решение:\n\nо наличии потребности в использовании этих средств на цели предоставления субсидии в текущем финансовом году;\n\nоб использовании этих средств на иные цели,  определенные федеральным законом о федеральном бюджете на текущий финансовый год и плановый период,  при условии сокращения субсидий,  предусмотренных данным федеральным законом и подлежащих предоставлению в текущем финансовом году соответствующим государственной корпорации (компании) ,  публично-правовой компании на указанные цели;\n\n6)  порядок и сроки представления отчетности об осуществлении расходов,  источником финансового обеспечения которых является субсидия,  предоставленная в целях финансового обеспечения затрат государственной корпорации (компании) ,  публично-правовой компании,  а также о достижении государственной корпорацией (компанией) ,  публично-правовой компанией,  юридическими лицами,  акции (доли)  которых принадлежат указанным государственной корпорации (компании) ,  публично-правовой компании,  и (или)  дочерними обществами таких юридических лиц результатов предоставления субсидии (иных показателей) ; (В редакции Федерального закона от 01.04.2020 № 71-ФЗ)\n\n7)  положения,  устанавливающие право получателя средств федерального бюджета,  предоставляющего субсидию,  на проведение проверок соблюдения государственной корпорацией (компанией) ,  публично-правовой компанией условий,  установленных соглашением о предоставлении субсидии;\n\n8)  ответственность государственной корпорации (компании) ,  публично-правовой компании за нарушение условий,  определенных соглашением о предоставлении субсидии.\n\n10. При предоставлении предусмотренной настоящей статьей субсидии государственной корпорации,  публично-правовой компании,  осуществляющим в соответствии с настоящим Кодексом полномочия главного распорядителя бюджетных средств и получателя бюджетных средств,  положения,  подлежащие в соответствии с пунктом 9 настоящей статьи включению в соглашение о предоставлении субсидии,  устанавливаются нормативными правовыми актами,  указанными в пунктах 2 и (или)  4 настоящей статьи. (В редакции Федерального закона от 22.12.2020 № 448-ФЗ)\n\n11. Соглашения о предоставлении субсидий могут заключаться на срок,  превышающий срок действия доведенных лимитов бюджетных обязательств,  в пределах средств,  предусмотренных на соответствующие цели решениями,  указанными в пункте 2 настоящей статьи,  или в случаях,  предусмотренных иными решениями  Правительства  Российской Федерации,  которые принимаются в определяемом Правительством Российской Федерации порядке. (В редакции федеральных законов от 15.10.2020 № 327-ФЗ,  от 30.04.2021 № 108-ФЗ)\n\nЗаключение договора (соглашения)  о предоставлении субсидии государственной корпорации (компании) ,  публично-правовой компании,  являющейся стороной соглашения о защите и поощрении капиталовложений,  заключенного в порядке,  установленном Федеральным законом от 1 апреля 2020 года № 69-ФЗ \"О защите и поощрении капиталовложений в Российской Федерации\",  на срок,  превышающий срок действия утвержденных лимитов бюджетных обязательств,  осуществляется в пределах сроков и объемов возмещения затрат,  определяемых в соответствии с указанным Федеральным законом. (Дополнение абзацем - Федеральный закон от 30.04.2021 № 108-ФЗ)\n\n12. В случаях,  определенных федеральными законами (за исключением федерального закона о федеральном бюджете) ,  иными нормативными правовыми актами о создании публично-правовых компаний,  государственным корпорациям (компаниям) ,  публично-правовым компаниям предоставляются субсидии на цели,  указанные в подпункте 3 пункта 1 настоящей статьи,  на осуществление ими капитальных вложений в целях строительства объектов капитального строительства,  подлежащих передаче в государственную собственность Российской Федерации.\n\nПереданные в государственную собственность Российской Федерации объекты капитального строительства,  указанные в абзаце первом настоящего пункта,  закрепляются в установленном порядке на праве оперативного управления за федеральными государственными учреждениями либо на праве оперативного управления или хозяйственного ведения за федеральными государственными унитарными предприятиями с последующим увеличением стоимости основных средств,  находящихся на праве оперативного управления у федеральных государственных учреждений либо на праве оперативного управления или хозяйственного ведения у федеральных государственных унитарных предприятий,  а также увеличением уставного фонда указанных предприятий,  основанных на праве хозяйственного ведения,  в соответствии с решениями,  указанными в пункте 2 настоящей статьи.\n\n121. В случае предоставления субсидий на цели,  предусмотренные подпунктом 21 пункта 1 настоящей статьи,  исключительные права на созданные или приобретенные за счет средств федерального бюджета программы для электронных вычислительных машин и иные результаты интеллектуальной деятельности,  связанные с созданием и развитием соответствующих государственных информационных систем,  на технические средства,  предназначенные для обработки информации,  содержащейся в государственных информационных системах,  в том числе программно-технические средства и средства защиты информации,  приобретенные за счет средств федерального бюджета,  а также права использования указанных программ,  иных результатов интеллектуальной деятельности,  технических средств принадлежат Российской Федерации.\n\nГосударственная регистрация прав,  указанных в абзаце первом настоящего пункта,  обеспечивается в установленном порядке федеральными органами государственной власти,  предоставляющими субсидии.\n\nПереданные в государственную собственность Российской Федерации технические средства,  указанные в абзаце первом настоящего пункта,  закрепляются в установленном порядке за федеральными органами государственной власти,  предоставляющими субсидии.\n\nВ соглашение о предоставлении субсидии в дополнение к предусмотренным пунктом 9 настоящей статьи положениям включаются положения об условиях предоставления государственным корпорациям (компаниям) ,  публично-правовым компаниям прав использования программ для электронных вычислительных машин и иных результатов интеллектуальной деятельности,  связанных с созданием и развитием соответствующих государственных информационных систем,  и об условиях пользования техническими средствами,  предназначенными для обработки информации,  содержащейся в государственных информационных системах,  необходимых для реализации определенных федеральными законами функций оператора таких систем.\n\n(Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\n13. В случае нарушения государственной корпорацией (компанией) ,  публично-правовой компанией целей,  условий и порядка предоставления предусмотренной настоящей статьей субсидии соответствующие средства подлежат возврату государственной корпорацией (компанией) ,  публично-правовой компанией в федеральный бюджет в порядке,  определенном нормативным правовым актом,  указанным в пункте 4 настоящей статьи.\n\n(Дополнение статьей - Федеральный закон от 18.07.2017 № 178-ФЗ)","article_title":"Статья 78.4. Предоставление субсидий в целях финансового обеспечения исполнения государственного (муниципального)  социального заказа на оказание государственных (муниципальных)  услуг в социальной сфере","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ee4c83ece049212bcc3ad9df0eef15115cf513480bc8229bb30dbdb0f2480c9a"},{"code_id":"BK_RF","article_number":"78.5","version_date":"1998-07-31","article_text":"1. Информация о субсидиях юридическим лицам,  индивидуальным предпринимателям,  физическим лицам - производителям товаров,  работ,  услуг,  включая гранты в форме субсидий,  предоставляемых в соответствии с пунктами 1 и 7 статьи 78,  пунктами 2 и 4 статьи 781 настоящего Кодекса,  в том числе предусмотренных законом (решением)  о бюджете (законом (решением)  о внесении изменений в закон (решение)  о бюджете) ,  размещается на едином портале бюджетной системы Российской Федерации в информационно-телекоммуникационной сети \"Интернет\" в соответствии с порядком размещения такой информации,  установленным Министерством финансов Российской Федерации в соответствии с абзацем сорок третьим статьи 165 настоящего Кодекса,  за исключением случая,  указанного в абзаце втором настоящего пункта.\n\nИнформация о субсидиях,  предоставляемых из бюджетов субъектов Российской Федерации,  местных бюджетов,  указанная в абзаце первом настоящего пункта,  размещается на ином сайте с размещением на едином портале бюджетной системы Российской Федерации указателей страниц такого сайта в случае принятия высшим должностным лицом субъекта Российской Федерации,  в бюджете которого расчетная доля межбюджетных трансфертов из федерального бюджета (за исключением субвенций)  в течение двух из трех последних отчетных финансовых лет не превышала 20 процентов объема собственных доходов консолидированного бюджета субъекта Российской Федерации,  главой муниципального образования,  находящегося на территории указанного субъекта Российской Федерации,  соответствующего решения. (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n2. Получатели субсидий,  указанных в пункте 1 настоящей статьи,  определяются:\n\n1)  в соответствии с международными договорами Российской Федерации,  федеральными законами,  законами (решениями)  о бюджете,  решениями Президента Российской Федерации,  высшего должностного лица субъекта Российской Федерации,  главы муниципального образования (за исключением главы муниципального образования,  входящего в состав представительного органа муниципального образования и исполняющего полномочия его председателя) ,  решениями,  принимаемыми Правительством Российской Федерации,  высшими исполнительными органами субъектов Российской Федерации (местными администрациями)  в целях использования бюджетных ассигнований,  зарезервированных в составе бюджетных ассигнований,  утвержденных законом (решением)  о бюджете; (В редакции  федеральных законов от 14.04.2023 № 128-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\n2)  по результатам проведения отбора получателей субсидий.\n\n3. Отбор получателей субсидий,  указанных в пункте 1 настоящей статьи,  осуществляется на конкурентной основе следующими способами:\n\n1)  запрос предложений - проведение отбора получателей субсидий исходя из соответствия участников отбора получателей субсидий категориям и (или)  критериям и очередности поступления предложений (заявок)  на участие в отборе получателей субсидий;\n\n2)  конкурс - проведение отбора получателей субсидий исходя из наилучших условий достижения результатов предоставления субсидий.\n\n4. Отбор получателей субсидий,  указанных в пункте 1 настоящей статьи,  предоставляемых из федерального бюджета,  бюджетов субъектов Российской Федерации,  местных бюджетов,  осуществляется в соответствии с порядком,  установленным Правительством Российской Федерации,  за исключением случая,  указанного в абзаце втором настоящего пункта.\n\nВ случае принятия решения высшим исполнительным органом субъекта Российской Федерации (местной администрацией муниципального образования)  отбор получателей субсидий,  указанных в пункте 1 настоящей статьи,  предоставляемых из бюджетов субъектов Российской Федерации (местных бюджетов) ,  осуществляется в порядке,  определенном нормативными правовыми актами высшего исполнительного органа субъекта Российской Федерации (муниципальными правовыми актами местной администрации)  или актами уполномоченных им органов государственной власти субъекта Российской Федерации (органов местного самоуправления) ,  которые регулируют предоставление субсидий и которые должны соответствовать общим требованиям,  установленным Правительством Российской Федерации,  за исключением случая,  указанного в абзаце третьем настоящего пункта. (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nВысший исполнительный орган субъекта Российской Федерации (местная администрация муниципального образования)  вправе определить порядок отбора получателей субсидий,  указанных в пункте 1 настоящей статьи,  предоставляемых из бюджетов субъектов Российской Федерации (местных бюджетов) ,  нормативным правовым актом высшего исполнительного органа субъекта Российской Федерации (муниципальным правовым актом местной администрации) ,  который должен соответствовать общим требованиям,  установленным Правительством Российской Федерации. (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n5. При предоставлении субсидий,  указанных в пункте 1 настоящей статьи,  из федерального бюджета отбор получателей субсидий осуществляется в государственной интегрированной информационной системе управления общественными финансами \"Электронный бюджет\" или в иных государственных информационных системах,  определенных порядком осуществления отбора получателей субсидий,  установленным Правительством Российской Федерации в соответствии с пунктом 4 настоящей статьи,  в рамках информационного взаимодействия с государственной интегрированной информационной системой управления общественными финансами \"Электронный бюджет\".\n\nПри предоставлении субсидий,  указанных в пункте 1 настоящей статьи,  из бюджетов субъектов Российской Федерации,  местных бюджетов отбор получателей субсидий осуществляется в государственной интегрированной информационной системе управления общественными финансами \"Электронный бюджет\",  за исключением случая,  установленного абзацем третьим настоящего пункта.\n\nПри предоставлении субсидий,  указанных в пункте 1 настоящей статьи,  из бюджетов субъектов Российской Федерации,  в которых расчетная доля межбюджетных трансфертов из федерального бюджета (за исключением субвенций)  в течение двух из трех последних отчетных финансовых лет не превышала 20 процентов объема собственных доходов консолидированного бюджета субъекта Российской Федерации,  бюджетов муниципальных образований,  находящихся на территориях указанных субъектов Российской Федерации,  отбор получателей субсидий осуществляется в государственных информационных системах субъектов Российской Федерации,  в том числе в рамках информационного взаимодействия с государственной интегрированной информационной системой управления общественными финансами \"Электронный бюджет\",  если высшим исполнительным органом соответствующего субъекта Российской Федерации определены такие информационные системы.\n\n(Пункт в редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n6. При проведении отбора получателей субсидий,  указанных в пункте 1 настоящей статьи,  взаимодействие главного распорядителя бюджетных средств как получателя бюджетных средств,  предоставляющего субсидии,  с участниками отбора получателей субсидий осуществляется с использованием документов в электронной форме. Обеспечение доступа к государственной интегрированной информационной системе управления общественными финансами \"Электронный бюджет\",  а также к государственным информационным системам,  указанным в пункте 5 настоящей статьи,  осуществляется с использованием федеральной государственной информационной системы \"Единая система идентификации и аутентификации в инфраструктуре,  обеспечивающей информационно-технологическое взаимодействие информационных систем,  используемых для предоставления государственных и муниципальных услуг в электронной форме\" (далее - единая система идентификации и аутентификации)  и (или)  государственных информационных систем субъектов Российской Федерации,  обеспечивающих взаимодействие с единой системой идентификации и аутентификации.\n\n7. Информация о проведении отбора получателей субсидий размещается на едином портале бюджетной системы Российской Федерации,  за исключением случая,  указанного в абзаце втором настоящего пункта.\n\nИнформация о проведении отбора получателей субсидий,  указанных в абзаце втором пункта 1 настоящей статьи,  предоставляемых из бюджетов субъектов Российской Федерации,  в которых расчетная доля межбюджетных трансфертов из федерального бюджета (за исключением субвенций)  в течение двух из трех последних отчетных финансовых лет не превышала 20 процентов объема собственных доходов консолидированного бюджета субъекта Российской Федерации,  бюджетов муниципальных образований,  находящихся на территориях указанных субъектов Российской Федерации,  размещается в случае принятия соответствующего решения высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования на ином сайте с размещением на едином портале бюджетной системы Российской Федерации указателей страниц такого сайта. (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n8. В случае,  если информация о субсидиях и (или)  получателях субсидий содержит сведения,  составляющие государственную тайну,  или информация о субсидиях является информацией ограниченного доступа,  положения пунктов 1,  5 - 7 настоящей статьи не применяются.\n\nВ случае,  если информация о получателях субсидий является информацией ограниченного доступа,  положения пункта 7 настоящей статьи не применяются в отношении размещения информации о получателях субсидий.\n\n(Пункт в редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 19.12.2022 № 521-ФЗ)","article_title":"Статья 78.5. Унификация и стандартизация предоставления субсидий юридическим лицам,  индивидуальным предпринимателям,  физическим лицам - производителям товаров,  работ,  услуг","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81a08aba9d5c8e36a05dd1e3138060106c8be42a2ab8579ce863a6b3b1a05acd"},{"code_id":"BK_RF","article_number":"79","version_date":"1998-07-31","article_text":"1. В бюджетах бюджетной системы Российской Федерации,  в том числе в рамках государственных (муниципальных)  программ,  могут предусматриваться бюджетные ассигнования на осуществление бюджетных инвестиций в форме капитальных вложений в объекты государственной (муниципальной)  собственности в соответствии с решениями,  указанными в пунктах 2 и 3 настоящей статьи,  с учетом положений статьи 1791 настоящего Кодекса. (В редакции  Федерального закона от 25.12.2023 № 628-ФЗ)\n\nОбъекты капитального строительства,  созданные в результате осуществления бюджетных инвестиций,  или объекты недвижимого имущества,  приобретенные в государственную (муниципальную)  собственность в результате осуществления бюджетных инвестиций,  закрепляются в установленном порядке на праве оперативного управления или хозяйственного ведения за государственными (муниципальными)  учреждениями,  государственными (муниципальными)  унитарными предприятиями с последующим увеличением стоимости основных средств,  находящихся на праве оперативного управления у государственных (муниципальных)  учреждений либо на праве оперативного управления или хозяйственного ведения у государственных (муниципальных)  унитарных предприятий,  а также уставного фонда указанных предприятий,  основанных на праве хозяйственного ведения,  либо включаются в состав государственной (муниципальной)  казны. (В редакции Федерального закона от 18.07.2017 № 178-ФЗ)\n\n2. Бюджетные инвестиции в объекты государственной собственности Российской Федерации,  государственной собственности субъекта Российской Федерации,  муниципальной собственности и принятие решений о подготовке и реализации бюджетных инвестиций в указанные объекты осуществляются в порядках,  установленных соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (В редакции  федеральных законов от 22.10.2014 № 311-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\n3. Решения о подготовке и реализации бюджетных инвестиций в объекты государственной собственности Российской Федерации,  находящиеся в оперативном управлении или хозяйственном ведении:\n\nфедеральных государственных учреждений стоимостью 3 миллиарда рублей и более,  а также федеральных государственных загранучреждений и федеральных государственных унитарных предприятий независимо от стоимости принимаются в форме правовых актов  Правительства  Российской Федерации; (В редакции федеральных законов от 22.10.2014 № 311-ФЗ,  от 22.12.2020 № 448-ФЗ)\n\nфедеральных государственных учреждений стоимостью менее 3 миллиардов рублей принимаются в установленном Правительством Российской Федерации порядке,  в том числе в случаях,  определенных Правительством Российской Федерации,  в форме правовых актов федеральных органов исполнительной власти или иных организаций,  осуществляющих в соответствии с настоящим Кодексом полномочия главного распорядителя средств федерального бюджета (органов управления государственными внебюджетными фондами Российской Федерации) . (В редакции  Федерального закона от 25.12.2023 № 628-ФЗ)\n\nВ случае принятия решений,  предусмотренных настоящим пунктом,  в отношении объектов государственной собственности Российской Федерации стоимостью 1, 5 миллиарда рублей и более информация о таких решениях направляется в Государственную Думу и Совет Федерации Федерального Собрания Российской Федерации в порядке,  установленном Правительством Российской Федерации,  в течение 10 дней со дня их принятия. (Дополнение абзацем - Федеральный закон от 22.12.2020 № 448-ФЗ)\n\n31. В случае,  если подготовка обоснования инвестиций для объекта капитального строительства в соответствии с законодательством Российской Федерации является обязательной,  решения о подготовке и реализации бюджетных инвестиций в такие объекты капитального строительства государственной (муниципальной)  собственности принимаются в том числе на основании подготовленного в установленном законодательством Российской Федерации порядке обоснования инвестиций и результатов его технологического и ценового аудита,  а также утвержденного задания на проектирование.\n\nПорядок принятия решений об осуществлении бюджетных инвестиций на подготовку обоснования инвестиций и проведение его технологического и ценового аудита за счет средств федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  местного бюджета и порядок осуществления указанных бюджетных инвестиций устанавливаются соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nРешения об осуществлении бюджетных инвестиций на подготовку обоснования инвестиций и проведение его технологического и ценового аудита за счет средств федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации принимаются Правительством Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 19.07.2018 № 222-ФЗ)\n\n4. Органам государственной власти (государственным органам) ,  органам управления государственными внебюджетными фондами,  органам местного самоуправления,  являющимся государственными (муниципальными)  заказчиками,  предоставляется право передать на безвозмездной основе на основании соглашений свои полномочия государственного (муниципального)  заказчика по заключению и исполнению от имени соответствующего публично-правового образования государственных (муниципальных)  контрактов от лица указанных органов при осуществлении бюджетных инвестиций в объекты государственной (муниципальной)  собственности (далее - соглашение о передаче полномочий)  бюджетным и автономным учреждениям,  в отношении которых указанные органы осуществляют функции и полномочия учредителей,  или государственным (муниципальным)  унитарным предприятиям,  в отношении которых указанные органы осуществляют права собственника имущества соответствующего публично-правового образования. (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\nУсловия передачи полномочий и порядок заключения соглашений о передаче полномочий в отношении объектов государственной собственности Российской Федерации,  государственной собственности субъектов Российской Федерации,  муниципальной собственности устанавливаются соответственно Правительством Российской Федерации,  высшими исполнительными органами субъектов Российской Федерации,  местными администрациями муниципальных образований. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nСоглашение о передаче полномочий может быть заключено в отношении нескольких объектов капитального строительства государственн\n\nс Федеральным законом от 13 июля 2020 года № 189-ФЗ \"О государственном (муниципальном)  социальном заказе на оказание государственных (муниципальных)  услуг в социальной сфере\" и принятыми в соответствии с ним иными нормативными правовыми актами Российской Федерации: (В редакции  Федерального закона от 22.06.2024 № 154-ФЗ)\n\n1)  на финансовое обеспечение выполнения бюджетными и автономными учреждениями государственного (муниципального)  задания,  предусмотренного статьей 692 настоящего Кодекса;\n\n2)  на оплату соглашения об оказании государственных (муниципальных)  услуг в социальной сфере,  заключенного по результатам конкурса;\n\n3)  на оплату соглашения о финансовом обеспечении (возмещении)  затрат,  связанных с оказанием государственных (муниципальных)  услуг в социальной сфере в соответствии с социальным сертификатом на получение государственной (муниципальной)  услуги в социальной сфере.\n\n2. Предоставление субсидий,  предусмотренных подпунктами 2 и 3 пункта 1 настоящей статьи,  из федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета осуществляется в порядке,  установленном соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования,  на основании соглашений,  заключенных по результатам отбора исполнителей государственных (муниципальных)  услуг в социальной сфере в соответствии с Федеральным законом от 13 июля 2020 года № 189-ФЗ \"О государственном (муниципальном)  социальном заказе на оказание государственных (муниципальных)  услуг в социальной сфере\" и принятыми в соответствии с ним иными нормативными правовыми актами Российской Федерации. (В редакции  федеральных законов от 14.04.2023 № 128-ФЗ,  от 22.06.2024 № 154-ФЗ)\n\n3. Соглашения,  предусмотренные настоящей статьей,  заключаются на срок оказания государственной (муниципальной)  услуги в социальной сфере,  указанный в государственном (муниципальном)  социальном заказе на оказание государственных (муниципальных)  услуг в социальной сфере,  если иной срок не установлен в соответствии с Федеральным законом от 13 июля 2020 года № 189-ФЗ \"О государственном (муниципальном)  социальном заказе на оказание государственных (муниципальных)  услуг в социальной сфере\". (В редакции  Федерального закона от 22.06.2024 № 154-ФЗ)\n\n31. Заключение соглашений о предоставлении субсидий,  предусмотренных подпунктами 2 и 3 пункта 1 настоящей статьи,  из федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета на срок,  превышающий срок действия утвержденных лимитов бюджетных обязательств,  осуществляется в случаях,  предусмотренных соответственно решениями  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации муниципального образования,  принимаемыми в порядке,  определяемом соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (Дополнение пунктом - Федеральный закон от 22.06.2024 № 154-ФЗ)\n\n4. Не использованные в отчетном финансовом году остатки субсидий,  предоставляемых в соответствии с соглашениями,  предусмотренными подпунктами 2 и 3 пункта 1 настоящей статьи,  остаются в распоряжении исполнителей государственных (муниципальных)  услуг в социальной сфере при условии соблюдения ими условий,  установленных такими соглашениями.\n\n(Дополнение статьей - Федеральный закон от 13.07.2020 № 192-ФЗ)","article_title":"Статья 79. Бюджетные инвестиции в объекты государственной (муниципальной)  собственности","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1e83f0a585f3ad36701a1ed5769a3a94a578da4f985e61013f538c7d777e971f"},{"code_id":"BK_RF","article_number":"79.1","version_date":"1998-07-31","article_text":"1. Осуществление бюджетных инвестиций из федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  местного бюджета в объекты государственной (муниципальной)  собственности,  которые не относятся (не могут быть отнесены)  соответственно к государственной собственности Российской Федерации,  государственной собственности субъекта Российской Федерации,  муниципальной собственности,  не допускается.\n\n2. Федеральным законом о федеральном бюджете с учетом положений статьи 1791 настоящего Кодекса могут предусматриваться субсидии бюджетам субъектов Российской Федерации на софинансирование капитальных вложений в объекты государственной собственности субъектов Российской Федерации,  которые осуществляются из бюджетов субъектов Российской Федерации,  или в целях предоставления субсидий местным бюджетам на софинансирование капитальных вложений в объекты муниципальной собственности,  которые осуществляются из местных бюджетов. (В редакции  Федерального закона от 25.12.2023 № 628-ФЗ)\n\nЗаконом о бюджете субъекта Российской Федерации могут предусматриваться субсидии местным бюджетам на софинансирование капитальных вложений в объекты муниципальной собственности,  которые осуществляются из местных бюджетов.\n\nПредоставление указанных субсидий бюджетам субъектов Российской Федерации (местным бюджетам)  осуществляется в соответствии с актами  Правительства  Российской Федерации (высшего исполнительного органа субъекта Российской Федерации)  и решениями Президента Российской Федерации,  а также за счет бюджетных ассигнований инвестиционного фонда в соответствии со статьей 1792 настоящего Кодекса. (В редакции  федеральных законов от 18.07.2017 № 178-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 25.12.2023 № 628-ФЗ)\n\nПредоставление указанных субсидий бюджетам субъектов Российской Федерации (местным бюджетам)  на софинансирование капитальных вложений в объекты капитального строительства и (или)  приобретения объектов недвижимого имущества,  которые не относятся (не могут быть отнесены)  к государственной собственности субъектов Российской Федерации (муниципальной собственности) ,  не допускается. (Дополнение абзацем - Федеральный закон от 27.12.2018 № 504-ФЗ)\n\n3. (Пункт утратил силу - Федеральный закон от 27.12.2018 № 504-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 28.12.2013 № 418-ФЗ)","article_title":"Статья 79.1. Особенности осуществления капитальных вложений в объекты государственной (муниципальной)  собственности и предоставления субсидий другим бюджетам бюджетной системы Российской Федерации на осуществление капитальных вложений в объекты государственной (муниципальной)  собственности","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91c51494e3cf4f7725b42e255b25fb730827c2151a907e7b356bbc6095825be1"}]$law7d0017$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
